import{z as n,x as o,o as A,c as C,q as i,j as t,D as a,d as e,s as r,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"扩散推理管线解剖","description":"","frontmatter":{"title":"扩散推理管线解剖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-serving-pipeline.md","filePath":"llm/diff-serving-pipeline.md","lastUpdated":1791063341000}'),m={name:"llm/diff-serving-pipeline.md"};function p(D,E,d,F,f,h){const B=o("Mermaid");return A(),C("div",null,[E[2]||(E[2]=i('<h1 id="扩散推理管线解剖" tabindex="-1">扩散推理管线解剖 <a class="header-anchor" href="#扩散推理管线解剖" aria-label="Permalink to &quot;扩散推理管线解剖&quot;">​</a></h1><div class="epigraph"><p>扩散服务慢不在「模型大」，而在同一段网络被调几百次；解剖管线就是找出哪一段在重复、哪一段只跑一次、哪一段可以提前算。</p><footer>—— 据 Ho 等 DDPM、Rombach 等 LDM 与 Stable Diffusion 推理实现整理</footer></div><p><a href="/llm/mm-map">上一课</a>把多模态服务侧的失败收成六族与三跑判据：失败多半静默，靠族坐标排障，监控面板先于故障建好，多模态的深钻线告一段落。本课程转向另一类生成负载：图像与视频的扩散生成服务化。主干已有 <a href="/llm/ddpm">DDPM</a>、<a href="/llm/latent-vae">潜空间与 VAE</a>、<a href="/llm/cfg-image">CFG 在图像生成</a>：加噪链、潜变量与引导的第一性都在那里立好。本课把「训练完的模型」切成服务视角的管线：一次请求到底执行了什么，时间与钱花在哪几段。后课的蒸馏、量化、批处理都默认你能按段报出成本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次文生图请求走五段：文本编码器把提示词编成条件嵌入；调度器按日程给出每步的噪声强度；去噪网络（UNet 或 DiT）从纯噪声潜变量迭代去噪 \\(T\\) 步；VAE 解码器把最终潜变量还原成像素；后处理做尺寸、格式与水印。缺口在五段的时间分布极不均匀：去噪网络要跑 \\(T\\) 次、开引导时再翻倍，其余各段只跑一两次，却常被当成「一个模型」整体优化。不解剖就优化，典型错误是给只占毫秒级的文本编码器配 GPU 常驻，却让占九成以上计算的去噪循环跑在未融合的算子上。</p><h3 id="一次请求的账" tabindex="-1">一次请求的账 <a class="header-anchor" href="#一次请求的账" aria-label="Permalink to &quot;一次请求的账&quot;">​</a></h3><p>以 SD 1.5 在 \\(512\\times512\\)、50 步、CFG \\(\\gamma=7.5\\) 为例：每步做有条件与无条件两次去噪前向，合计 \\(100\\) 次 UNet 前向，加一次 VAE 解码；潜变量是 \\(64\\times64\\times4\\)，UNet fp16 权重约 \\(860\\)M 参数、\\(1.7\\) GB。文本编码与调度器查表只占毫秒级，但前者输出可以缓存复用——同一提示词的嵌入是纯函数，这是扩散服务里最便宜的缓存。</p><p><span class="marginnote">50 步 × CFG 双前向 = 100 次去噪前向 + 1 次 VAE 解码。步数与引导是产品配置不是模型常数，前向次数按配置算，不能按模型算。</span></p><p><span class="marginnote">数字感受一下潜空间有多省：\\(512\\times512\\times3\\) 的原图约有 79 万个数值，压成 \\(64\\times64\\times4\\) 的潜变量后只剩约 1.6 万个，缩小约 48 倍。去噪循环全程在这个「小图」上进行，这就是扩散还能实时服务的前提——先在低维空间干活，最后才由 VAE 一次性放大回像素。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务化第一件事是把管线切成三类段：</p><ul><li><strong>一次性段</strong>：文本编码、控制条件预处理。输入不变则输出不变，可按提示词哈希缓存。</li><li><strong>循环段</strong>：去噪网络与调度器更新。\\(T\\) 次迭代共享同一份权重；扩散没有 KV 缓存，每步都从潜变量整张重算，这是与 LLM 推理最大的结构差异。</li><li><strong>收尾段</strong>：VAE 解码与后处理。解码是单次大变换，精度与显存敏感，常与去噪用不同精度。</li></ul><p>切完给每段计时：去噪循环应占端到端九成上下。若不是，先查批是否太小让 GPU 在循环间空转，或解码是否落在兜底精度上。调度器是查表不是网络：换采样器改的是循环次数与步长，不改权重，这给了服务端第一根「不改模型的旋钮」，也是下一课蒸馏的对照面。</p><p><span class="marginnote">「调度器是查表不是网络」翻译一下：调度器就是一张预先算好的时间表，写明第 1 步噪声多大、第 2 步多小……直到最后一步接近零。它没有任何可学习的参数，换采样器只是换一张表，权重一个字节都不动——所以调它不触发重新训练，是服务端最便宜的旋钮。</span></p>',14)),(A(),t(s,null,{default:a(()=>[r(B,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%AF%8D%20%2B%20%E5%B0%BA%E5%AF%B8%20%2B%20%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%E7%BC%96%E7%A0%81%EF%BC%9A%E4%B8%80%E6%AC%A1%E6%80%A7%EF%BC%8C%E5%8F%AF%E7%BC%93%E5%AD%98%22%5D%0A%20%20TXT%20--%3E%20LOOP%5B%22%E5%8E%BB%E5%99%AA%E5%BE%AA%E7%8E%AF%EF%BC%9AT%20%E6%AD%A5%20%C3%97%20CFG%20%E5%89%8D%E5%90%91%22%5D%0A%20%20LOOP%20--%3E%20DEC%5B%22VAE%20%E8%A7%A3%E7%A0%81%EF%BC%9A%E6%94%B6%E5%B0%BE%E6%AE%B5%22%5D%0A%20%20DEC%20--%3E%20POST%5B%22%E5%90%8E%E5%A4%84%E7%90%86%E4%B8%8E%E6%B0%B4%E5%8D%B0%22%5D%0A%20%20LOOP%20--%3E%7C%E6%AF%8F%E6%AD%A5%7C%20SCH%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E6%9F%A5%E8%A1%A8%EF%BC%9A%E5%99%AA%E5%A3%B0%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20SCH%20--%3E%20LOOP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"循环段主导成本的原因：去噪前向的 FLOPs 随潜变量面积增长，注意力项还随 token 数平方增长；\\(T\\) 与 CFG 是乘在头上的倍数。于是服务级性能问题几乎都能约化成两条：「减少前向次数」与「降低单次前向成本」，前者通向蒸馏与调度，后者通向量化与批处理。条件嵌入缓存之所以成立，是文本编码器的纯函数性；VAE 解码不能这样缓存，因为它接在随机性最强的最终潜变量后面，输入几乎不重复。",-1)),(A(),t(s,null,{default:a(()=>[r(B,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLOW%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E5%A4%AA%E6%85%A2%EF%BC%8C%E5%85%88%E6%8C%89%E6%AE%B5%E8%AE%A1%E6%97%B6%22%5D%20--%3E%20Q%7B%22%E7%93%B6%E9%A2%88%E8%90%BD%E5%9C%A8%E5%93%AA%E7%B1%BB%E6%AE%B5%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%BE%AA%E7%8E%AF%E6%AE%B5%EF%BC%9A%E5%89%8D%E5%90%91%E6%AC%A1%E6%95%B0%E5%A4%9A%22%7C%20N%5B%22%E5%87%8F%E5%B0%91%E5%89%8D%E5%90%91%E6%AC%A1%E6%95%B0%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BE%AA%E7%8E%AF%E6%AE%B5%EF%BC%9A%E5%8D%95%E6%AC%A1%E5%A4%AA%E8%B4%B5%22%7C%20C%5B%22%E9%99%8D%E4%BD%8E%E5%8D%95%E6%AC%A1%E5%89%8D%E5%90%91%E6%88%90%E6%9C%AC%22%5D%0A%20%20N%20--%3E%20N1%5B%22%E8%92%B8%E9%A6%8F%EF%BC%9A%E6%AD%A5%E6%95%B0%E6%8A%98%E5%8D%8A%E5%86%8D%E6%8A%98%E5%8D%8A%22%5D%0A%20%20N%20--%3E%20N2%5B%22%E6%8D%A2%E8%B0%83%E5%BA%A6%E5%99%A8%EF%BC%9A%E6%94%B9%E6%AD%A5%E9%95%BF%E4%B8%8E%E6%AC%A1%E6%95%B0%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E9%87%8F%E5%8C%96%EF%BC%9A%E6%9D%83%E9%87%8D%E4%B8%8E%E6%BF%80%E6%B4%BB%E9%99%8D%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E6%89%B9%E5%A4%84%E7%90%86%EF%BC%9A%E5%87%91%E6%89%B9%E5%A1%AB%E6%BB%A1%20GPU%22%5D%0A%20%20N1%20--%3E%20V%5B%22%E7%BB%93%E6%9E%9C%E8%BF%87%E8%B4%A8%E9%87%8F%E8%AF%84%E6%B5%8B%E9%97%A8%22%5D%0A%20%20C1%20--%3E%20V%0A%20%20N2%20--%3E%20V%0A%20%20C2%20--%3E%20V%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p>与 LLM 服务对照：自回归的长度运行时才确定，扩散的 \\(T\\) 在配置里就定了；自回归靠 KV 缓存把历史变增量，扩散每步对整张潜变量重算。这两条差异决定调度器形状不同，而「凑批复用」又与<a href="/llm/continuous-batching">连续批处理</a>形似神不似——形似在凑批，神不似在没有逐 token 的增量结构。</p><p><span class="marginnote">常见误区：做过 LLM 推理的人常以为扩散也能挂一个 KV 缓存，把「已算过的部分」存起来逐步增量。实际上扩散每一步的潜变量都是全新的一张图，上一步的中间结果对下一步毫无复用价值——这就是为什么扩散批内所有请求必须步调一致地走完 \\(T\\) 步，而 LLM 可以各生成各的长度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只解剖标准文生图管线：图生图多一段 VAE 编码，视频多一个时间维，都是后课的增量。段计时依赖实现，算子融合差的实现会让解码或预处理虚高，先修实现再谈分布。CFG 的机制与 \\(\\gamma\\) 的取舍在 <a href="/llm/cfg-image">CFG 在图像生成</a>已立，本课只把它当前向次数的乘数；蒸馏后学生不再需要双前向，那是下一课的缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>管线五段：文本编码、调度、去噪循环、VAE 解码、后处理；循环段占九成计算。</li><li>前向次数 = 步数 × 引导倍数，是服务级成本的第一公式。</li><li>文本编码是纯函数，条件嵌入缓存是扩散服务最便宜的复用。</li><li>扩散无 KV 增量结构，每步整张重算，批内步调一致是调度的前提。</li><li>性能问题约化成「少跑前向」与「跑便宜前向」，分别通向蒸馏与量化。</li><li>出处：Ho 等 DDPM、Rombach 等 LDM、Ho &amp; Salimans CFG；量级据 Stable Diffusion 1.5 公开规格。</li></ul>',6))])}const T=n(m,[["render",p]]);export{u as __pageData,T as default};
